create function private.record_qualified_notification_view(p_kind text,p_source_id text,p_creator uuid,p_viewer uuid)
returns boolean language plpgsql security definer set search_path='' as $$
declare v_day date:=(now() at time zone 'UTC')::date; v_due timestamptz;
begin
  if p_creator is null or p_viewer is null or p_creator=p_viewer
    or public.is_account_access_restricted(p_creator::text) or public.is_account_access_restricted(p_viewer::text)
    or public.has_channel_audience_block_between(p_creator::text,p_viewer::text) then return false; end if;
  insert into public.notification_qualified_views(creator_user_id,viewer_user_id,view_kind,source_id,view_day)
    values(p_creator,p_viewer,p_kind,p_source_id,v_day) on conflict do nothing;
  if not found then return true; end if;
  v_due:=((v_day+1)::timestamp at time zone 'UTC');
  perform private.enqueue_notification_activity('view-summary:'||p_creator::text||':'||p_kind||':'||v_day::text,
    p_kind||'_view_summary',v_day::text,null,p_creator,jsonb_build_object('viewDay',v_day,'viewKind',p_kind),
    v_due,v_due+interval '2 days');
  return true;
end $$;
revoke all on function private.record_qualified_notification_view(text,text,uuid,uuid) from public,anon,authenticated,service_role;

create function public.begin_video_notification_view(p_video_id uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_session jsonb; v_user uuid:=auth.uid(); v_generation uuid; v_owner uuid; v_id uuid; v_access jsonb;
begin
  if v_user is null then return null; end if;
  v_session:=public.wave1_session_authority_readback();
  if v_session->>'state' is distinct from 'ACTIVE' or coalesce((v_session->>'restoreOnly')::boolean,false)
    or public.is_account_access_restricted(v_user::text) then return null; end if;
  v_generation:=(v_session->>'sessionGeneration')::uuid;
  select owner_id into v_owner from public.videos where id=p_video_id;
  if not found or v_owner=v_user or public.is_account_access_restricted(v_owner::text)
    or public.has_channel_audience_block_between(v_owner::text,v_user::text) then return null; end if;
  v_access:=public.resolve_creator_content_access('creator_video',p_video_id);
  if not coalesce((v_access->>'allowed')::boolean,false) then return null; end if;
  insert into public.notification_video_view_sessions(viewer_user_id,session_generation,video_id,creator_user_id)
    values(v_user,v_generation,p_video_id,v_owner)
    on conflict(viewer_user_id,video_id,view_day) do update set
      started_at=case when notification_video_view_sessions.session_generation=excluded.session_generation
        and (notification_video_view_sessions.completed_at is not null
          or notification_video_view_sessions.started_at>=now()-interval '2 hours')
        then notification_video_view_sessions.started_at else now() end,
      session_generation=excluded.session_generation
    returning id into v_id;
  return v_id;
end $$;

create function private.spectator_notification_view_owner(p_record_id uuid,p_viewer uuid)
returns uuid language plpgsql stable security definer set search_path='' as $$
declare v_record public.spectator_hls_playback_records; v_session public.room_broadcast_sessions; v_owner text;
begin
  if p_viewer is null or p_viewer is distinct from auth.uid() then return null; end if;
  select * into v_record from public.spectator_hls_playback_records where id=p_record_id;
  if not found or v_record.playback_status<>'live' or not v_record.is_spectator_playback_enabled
    or v_record.requires_premium or v_record.requires_ticket or nullif(v_record.playlist_path,'') is null
    or v_record.rights_status not in ('creator_owned','chillywood_original','licensed_for_public_stream') then return null; end if;
  select * into v_session from public.room_broadcast_sessions where id=v_record.broadcast_session_id;
  if not found or v_session.ended_at is not null
    or v_session.broadcast_status in ('ended','failed_later','cancelled','stopping_later')
    or v_session.egress_status in ('stopped_later','failed_later')
    or not (v_session.broadcast_status='active_later' or v_session.egress_status='active_later')
    or v_record.host_user_id is distinct from v_session.host_user_id
    or coalesce(nullif(v_record.channel_user_id,''),v_record.host_user_id) is distinct from
       coalesce(nullif(v_session.channel_user_id,''),v_session.host_user_id)
    or v_record.source_room_id is distinct from coalesce(nullif(v_session.source_room_id,''),
       nullif(v_session.watch_party_room_id,''),nullif(v_session.creator_event_id,''))
    or v_record.watch_party_room_id is distinct from v_session.watch_party_room_id
    or v_record.creator_event_id is distinct from v_session.creator_event_id
    or not v_session.is_spectator_playback_enabled or v_session.requires_premium or v_session.requires_ticket
    or v_session.rights_status not in ('creator_owned','chillywood_original','licensed_for_public_stream')
    or nullif(v_session.hls_playback_url,'') is null then return null; end if;
  if v_record.visibility='public' and v_record.access_type='public_free' and v_record.is_publicly_watchable
    and v_session.access_type='public_free' and v_session.is_publicly_watchable
    and v_session.playback_url_status='public_safe_available' and v_session.metadata->>'d7f_public_safe_approved'='true'
  then null;
  elsif v_record.visibility='circle' and v_record.access_type='circle' and not v_record.is_publicly_watchable
    and v_session.access_type='circle' and not v_session.is_publicly_watchable
    and v_session.playback_url_status='circle_safe_available' and v_session.metadata->>'circle_spectator_approved'='true'
    and public.can_read_circle_spectator_playback_record(p_record_id,p_viewer::text)
  then null;
  else return null; end if;
  v_owner:=coalesce(nullif(v_record.channel_user_id,''),nullif(v_record.host_user_id,''));
  if v_owner is null or v_owner !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    or v_owner=p_viewer::text or public.is_account_access_restricted(v_owner)
    or public.is_account_access_restricted(p_viewer::text)
    or public.has_channel_audience_block_between(v_owner,p_viewer::text) then return null; end if;
  -- Bind the playback to its still-current, authoritative live source.
  if v_session.source_type in ('watch_party_room','live_stage_room') then
    if not exists(select 1 from public.watch_party_rooms r
      where r.party_id=v_record.source_room_id and r.is_active
        and r.host_user_id::text=v_session.host_user_id) then return null; end if;
  elsif v_session.source_type='creator_event' then
    if not exists(select 1 from public.creator_events e
      where e.id::text=v_session.creator_event_id and e.host_user_id=v_session.host_user_id
        and e.status='live_now' and (e.ends_at is null or e.ends_at>now())) then return null; end if;
  else return null; end if;
  return v_owner::uuid;
end $$;
revoke all on function private.spectator_notification_view_owner(uuid,uuid) from public,anon,authenticated,service_role;

create function public.begin_spectator_notification_view(p_record_id uuid)
returns uuid language plpgsql security definer set search_path='' as $$
declare v_session jsonb; v_owner uuid; v_id uuid; v_generation uuid;
begin
  if auth.uid() is null then return null; end if;
  v_session:=public.wave1_session_authority_readback();
  if v_session->>'state' is distinct from 'ACTIVE' or coalesce((v_session->>'restoreOnly')::boolean,false) then return null; end if;
  v_owner:=private.spectator_notification_view_owner(p_record_id,auth.uid());
  if v_owner is null then return null; end if;
  v_generation:=(v_session->>'sessionGeneration')::uuid;
  insert into public.notification_video_view_sessions(viewer_user_id,session_generation,spectator_record_id,creator_user_id)
    values(auth.uid(),v_generation,p_record_id,v_owner)
    on conflict(viewer_user_id,spectator_record_id,view_day) do update set
      started_at=case when notification_video_view_sessions.session_generation=excluded.session_generation
        and (notification_video_view_sessions.completed_at is not null
          or notification_video_view_sessions.started_at>=now()-interval '2 hours')
        then notification_video_view_sessions.started_at else now() end,
      session_generation=excluded.session_generation
    returning id into v_id;
  return v_id;
end $$;

create function public.complete_content_notification_view(p_view_id uuid)
returns boolean language plpgsql security definer set search_path='' as $$
declare v_session jsonb; v_row public.notification_video_view_sessions; v_owner uuid; v_access jsonb;
begin
  if auth.uid() is null then return false; end if;
  v_session:=public.wave1_session_authority_readback();
  if v_session->>'state' is distinct from 'ACTIVE' or coalesce((v_session->>'restoreOnly')::boolean,false)
    then return false; end if;
  select * into v_row from public.notification_video_view_sessions where id=p_view_id and viewer_user_id=auth.uid() for update;
  if not found or v_row.session_generation::text is distinct from v_session->>'sessionGeneration'
    or v_row.started_at>now()-interval '10 seconds' or v_row.started_at<now()-interval '2 hours'
    or v_row.view_day<>(now() at time zone 'UTC')::date then return false; end if;
  if v_row.video_id is not null then
    select owner_id into v_owner from public.videos where id=v_row.video_id;
    if not found or v_owner<>v_row.creator_user_id then return false; end if;
    v_access:=public.resolve_creator_content_access('creator_video',v_row.video_id);
    if not coalesce((v_access->>'allowed')::boolean,false) then return false; end if;
    if not private.record_qualified_notification_view('video',v_row.video_id::text,v_owner,auth.uid()) then return false; end if;
  else
    v_owner:=private.spectator_notification_view_owner(v_row.spectator_record_id,auth.uid());
    if v_owner is null or v_owner<>v_row.creator_user_id then return false; end if;
    if not private.record_qualified_notification_view('live','hls:'||v_row.spectator_record_id::text,v_owner,auth.uid()) then return false; end if;
  end if;
  update public.notification_video_view_sessions set completed_at=coalesce(completed_at,now()) where id=v_row.id;
  return true;
end $$;
revoke all on function public.begin_video_notification_view(uuid),public.begin_spectator_notification_view(uuid),public.complete_content_notification_view(uuid) from public,anon,service_role;
grant execute on function public.begin_video_notification_view(uuid),public.begin_spectator_notification_view(uuid),public.complete_content_notification_view(uuid) to authenticated;

create function private.qualify_live_notification_view()
returns trigger language plpgsql security definer set search_path='' as $$
declare v_owner uuid; v_authority jsonb; v_session uuid;
begin
  -- Only a viewer's current authenticated heartbeat qualifies; host actions,
  -- removed/reconnecting rows and mere initial membership do not count.
  if not public.whole_app_exact_current_session_authority_internal()
    or auth.uid()::text<>new.user_id or new.membership_state<>'active'
    or old.membership_state<>'active' or new.left_at is not null or old.left_at is not null
    or new.joined_at>now()-interval '10 seconds' or old.last_seen_at<now()-interval '45 seconds'
    or new.last_seen_at is not distinct from old.last_seen_at
    or new.last_seen_at<now()-interval '5 seconds' or new.last_seen_at>now()+interval '1 second'
    then return new; end if;
  select host_user_id into v_owner from public.watch_party_rooms where party_id=new.party_id and room_type='live' and is_active;
  if not found or v_owner=auth.uid() then return new; end if;
  v_session:=nullif(auth.jwt()->>'session_id','')::uuid;
  if v_session is null then return new; end if;
  v_authority:=public.resolve_watch_party_livekit_viewer_authority(new.party_id,auth.uid(),v_session);
  if coalesce((v_authority->>'allowed')::boolean,false) then
    perform private.record_qualified_notification_view('live',new.party_id,v_owner,auth.uid());
  end if;
  return new;
end $$;
revoke all on function private.qualify_live_notification_view() from public,anon,authenticated,service_role;
create trigger qualify_live_notification_view after update of last_seen_at on public.watch_party_room_memberships
  for each row execute function private.qualify_live_notification_view();

create or replace function private.resolve_view_notification_activity(p_event public.notification_activity_events)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_count integer; v_kind text; v_day date;
begin
  if p_event.event_kind not in ('video_view_summary','live_view_summary') or p_event.actor_user_id is not null then
    return '{"eligible":false}'::jsonb; end if;
  v_kind:=case when p_event.event_kind='video_view_summary' then 'video' else 'live' end;
  v_day:=(p_event.context->>'viewDay')::date;
  if v_day::text<>p_event.source_id or p_event.context->>'viewKind'<>v_kind or v_day>=(now() at time zone 'UTC')::date
    then return '{"eligible":false}'::jsonb; end if;
  select count(distinct q.viewer_user_id)::integer into v_count from public.notification_qualified_views q
    where q.creator_user_id=p_event.recipient_user_id and q.view_kind=v_kind and q.view_day=v_day
      and not public.is_account_access_restricted(q.viewer_user_id::text)
      and not public.has_channel_audience_block_between(q.creator_user_id::text,q.viewer_user_id::text)
      and ((v_kind='video' and exists(select 1 from public.videos v where v.id::text=q.source_id
        and v.owner_id=q.creator_user_id and v.quarantined_at is null and v.moderation_status in ('clean','reported')))
        or (v_kind='live' and (exists(select 1 from public.watch_party_rooms r where r.party_id=q.source_id
          and r.host_user_id=q.creator_user_id and r.room_type='live')
          or exists(select 1 from public.spectator_hls_playback_records r where 'hls:'||r.id::text=q.source_id
            and coalesce(nullif(r.channel_user_id,''),nullif(r.host_user_id,''))=q.creator_user_id::text
            and r.playback_status in ('live','ended') and r.visibility in ('public','circle')))));
  if v_count=0 then return '{"eligible":false}'::jsonb; end if;
  return jsonb_build_object('eligible',true,'category','view_summary','notification_type',p_event.event_kind,
    'title',case when v_kind='video' then 'Your video views' else 'Your live views' end,
    'body',v_count::text||case when v_count=1 then ' viewer watched your ' else ' viewers watched your ' end||
      case when v_kind='video' then 'videos on ' else 'live content on ' end||v_day::text||'.',
    'target_route','/channel-studio','target_entity_id',null,
    'target_context',jsonb_build_object('viewDay',v_day,'viewerCount',v_count,'viewKind',v_kind),
    'preference_key','view_summary_enabled');
end $$;
revoke all on function private.resolve_view_notification_activity(public.notification_activity_events) from public,anon,authenticated,service_role;
comment on table public.notification_qualified_views is
  'Private notification analytics only, never purchase, payout, access or popularity authority. Distinct authenticated viewers per source/day, aggregated per creator/day; no profile views.';

-- Notification plumbing only. Existing request/review/role and paid-access
-- functions remain unchanged; a notification never grants a speaking role.
create function private.seat_notification_uuid(p_value text)
returns uuid language plpgsql immutable set search_path='' as $$
begin return nullif(btrim(p_value),'')::uuid;
exception when invalid_text_representation then return null; end $$;

create function private.seat_notification_source(p_kind text,p_pass_id uuid)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare p public.paid_live_watch_party_passes; r public.watch_party_rooms;
  m public.watch_party_room_memberships; o public.paid_live_watch_party_offers;
  revision timestamptz; actor_id uuid; recipient_id uuid; state text;
begin
  if p_kind is null or p_kind not in ('live_watch_party_seat_requested','live_watch_party_seat_approved','live_watch_party_seat_rejected')
    then return '{"eligible":false}'; end if;
  select * into p from public.paid_live_watch_party_passes where id=p_pass_id;
  if not found or p.pass_type<>'live_watch_party_seat_pass' or p.status<>'active'
    or p.revoked_at is not null or p.refunded_at is not null then return '{"eligible":false}'; end if;
  select * into r from public.watch_party_rooms where party_id=p.party_id;
  if not found or r.room_type<>'live' or not r.is_active or r.host_user_id is distinct from p.creator_id
    or r.host_user_id=p.buyer_id then return '{"eligible":false}'; end if;
  select * into o from public.paid_live_watch_party_offers where id=p.offer_id;
  if not found or o.party_id<>p.party_id or o.creator_id<>p.creator_id or o.pass_type<>p.pass_type
    or not public.has_exact_live_watch_party_pass_internal(p.party_id,p.buyer_id,p.pass_type)
    then return '{"eligible":false}'; end if;
  select * into m from public.watch_party_room_memberships where party_id=p.party_id and user_id=p.buyer_id::text;
  if not found or m.membership_state not in ('active','reconnecting') or m.left_at is not null
    then return '{"eligible":false}'; end if;
  if exists(select 1 from public.paid_live_watch_party_offers access_offer where access_offer.party_id=p.party_id
    and access_offer.pass_type='live_watch_party_access_pass' and access_offer.status in ('sandbox','active')
    and (access_offer.starts_at is null or access_offer.starts_at<=now())
    and (access_offer.ends_at is null or access_offer.ends_at>now()))
    and not public.has_exact_live_watch_party_pass_internal(p.party_id,p.buyer_id,'live_watch_party_access_pass')
    then return '{"eligible":false}'; end if;
  if p_kind='live_watch_party_seat_requested' then
    if p.requested_at is null or p.approved_at is not null or p.rejected_at is not null
      or m.stage_role<>'listener' then return '{"eligible":false}'; end if;
    revision:=p.requested_at; actor_id:=p.buyer_id; recipient_id:=p.creator_id; state:='requested';
  elsif p_kind='live_watch_party_seat_approved' then
    if p.approved_at is null or p.requested_at is not null or p.rejected_at is not null
      or m.stage_role<>'speaker' or not m.can_speak then return '{"eligible":false}'; end if;
    revision:=p.approved_at; actor_id:=p.creator_id; recipient_id:=p.buyer_id; state:='approved';
  else
    if p.rejected_at is null or p.requested_at is not null or p.approved_at is not null
      or m.stage_role<>'listener' then return '{"eligible":false}'; end if;
    revision:=p.rejected_at; actor_id:=p.creator_id; recipient_id:=p.buyer_id; state:='rejected';
  end if;
  return jsonb_build_object('eligible',true,'actor',actor_id,'recipient',recipient_id,
    'partyId',p.party_id,'offerId',p.offer_id,'revision',revision,'state',state);
end $$;

create or replace function private.resolve_seat_notification_activity(p_event public.notification_activity_events)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare s jsonb:=private.seat_notification_source(p_event.event_kind,private.seat_notification_uuid(p_event.source_id));
begin
  if not coalesce((s->>'eligible')::boolean,false)
    or s->>'actor' is distinct from p_event.actor_user_id::text
    or s->>'recipient' is distinct from p_event.recipient_user_id::text
    or s->>'revision' is distinct from p_event.context->>'revision'
    or s->>'offerId' is distinct from p_event.context->>'offerId'
    then return '{"eligible":false}'; end if;
  return jsonb_build_object('eligible',true,'category',case when s->>'state'='requested'
    then 'creator_money_sale' else 'creator_money_purchase' end,'notification_type',p_event.event_kind,
    'title',case s->>'state' when 'requested' then 'Live Stage seat requested' when 'approved' then 'Live Stage seat approved'
      else 'Live Stage seat request not approved' end,
    'body',case s->>'state' when 'requested' then 'A viewer requested a speaking seat. Open the Stage to review it.'
      when 'approved' then 'The host approved your current speaking seat. Open the Stage to check your current role.'
      else 'The host did not approve this speaking-seat request. Your pass remains eligibility only.' end,
    'target_route','/watch-party/live-stage/[partyId]','target_entity_id',s->>'partyId',
    'target_context','{}'::jsonb,'preference_key','seat_activity_enabled');
end $$;

create function private.route_legacy_seat_notification_to_activity()
returns trigger language plpgsql security definer set search_path='' as $$
declare p public.paid_live_watch_party_passes; s jsonb; buyer uuid;
begin
  if new.source_type is distinct from 'live_watch_party_seat'
    or new.notification_type is null or new.notification_type not in ('live_watch_party_seat_requested','live_watch_party_seat_approved','live_watch_party_seat_rejected')
    then return new; end if;
  -- Until delivery is explicitly configured, retain the existing working bell
  -- path. Source deployment alone must not silently consume these notices.
  if not exists(select 1 from public.notification_activity_worker_config where singleton and enabled)
    then return new; end if;
  -- Only the exact current state emitted by the existing authoritative paths
  -- can become work. Invalid legacy attempts cannot bypass preferences either.
  buyer:=case when new.notification_type='live_watch_party_seat_requested' then new.actor_user_id else new.user_id end;
  select * into p from public.paid_live_watch_party_passes where offer_id=private.seat_notification_uuid(new.source_id)
    and buyer_id=buyer and party_id=new.target_entity_id and status='active' and pass_type='live_watch_party_seat_pass';
  if not found then return null; end if;
  s:=private.seat_notification_source(new.notification_type,p.id);
  if not coalesce((s->>'eligible')::boolean,false) or s->>'recipient' is distinct from new.user_id::text
    or (new.actor_user_id is not null and s->>'actor' is distinct from new.actor_user_id::text)
    or (new.notification_type<>'live_watch_party_seat_approved' and new.actor_user_id is null)
    or new.target_route is distinct from '/watch-party/live-stage/[partyId]'
    or new.target_context->>'seat_state' is distinct from s->>'state'
    then return null; end if;
  perform private.enqueue_notification_activity('seat:'||p.id||':'||new.notification_type||':'||md5(s->>'revision'),
    new.notification_type,p.id::text,private.seat_notification_uuid(s->>'actor'),private.seat_notification_uuid(s->>'recipient'),
    jsonb_build_object('revision',s->>'revision','offerId',p.offer_id),now(),now()+interval '24 hours');
  return null;
end $$;

revoke all on function private.seat_notification_uuid(text),private.seat_notification_source(text,uuid),
  private.resolve_seat_notification_activity(public.notification_activity_events),
  private.route_legacy_seat_notification_to_activity() from public,anon,authenticated,service_role;

-- Default-off preserves the existing seat bell; only configured activity
-- delivery replaces it with the tested common queue and preference path.
create trigger notification_seat_to_activity_before_insert before insert on public.notifications
  for each row execute function private.route_legacy_seat_notification_to_activity();

-- Notify the exact content owner after an existing operator decision. This
-- observer does not change enforcement, reporter privacy, or access authority.
create function private.notification_moderation_target(p_report public.safety_reports)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_target uuid; v_owner text; v_status text; v_expected text; v_route text:='/profile/[userId]'; v_kind text;
  v_action_at timestamptz; v_action_by text; v_thread uuid;
begin
  if p_report.status<>'actioned' or p_report.resolved_at is null or p_report.resolved_by is null
    or p_report.resolution_type not in ('target_hidden','target_removed','target_restored') then return null; end if;
  v_target:=public.admin_reports_safe_uuid(p_report.target_id);
  if v_target is null then return null; end if;
  v_expected:=case p_report.resolution_type when 'target_hidden' then 'hidden' when 'target_removed' then 'removed' else 'clean' end;
  case p_report.target_type
    when 'creator_video' then
      select owner_id::text,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.videos where id=v_target;
      v_route:='/channel-studio';
    when 'profile_post' then
      select user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.profile_posts where id=v_target and deleted_at is null;
    when 'profile_post_comment' then
      select user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.profile_post_comments where id=v_target and deleted_at is null;
    when 'creator_video_comment' then
      select user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.creator_video_comments where id=v_target and deleted_at is null;
    when 'social_attachment' then
      select owner_user_id,moderation_status,moderated_at,moderated_by into v_owner,v_status,v_action_at,v_action_by from public.social_attachments where id=v_target and deleted_at is null;
    when 'profile_media' then
      v_kind:=lower(coalesce(p_report.context->>'profileMediaKind',p_report.context->>'profile_media_kind',''));
      if v_kind not in ('avatar','background') then return null; end if;
      select user_id,case when v_kind='avatar' then profile_avatar_media_status else profile_background_media_status end,profile_media_updated_at
        into v_owner,v_status,v_action_at from public.user_profiles where user_id=v_target::text;
      v_expected:=case p_report.resolution_type when 'target_hidden' then 'flagged' when 'target_removed' then 'admin_removed' else 'active' end;
    when 'chat_message' then
      select sender_user_id,moderation_status,moderation_actioned_at,moderation_actioned_by,thread_id
        into v_owner,v_status,v_action_at,v_action_by,v_thread from public.chat_messages
        where id=v_target and moderation_report_id=p_report.id;
      if v_thread is null or v_thread::text is distinct from coalesce(p_report.context->>'threadId',p_report.context->>'thread_id')
        or not exists(select 1 from public.chat_thread_members where thread_id=v_thread and user_id=v_owner)
        then return null; end if;
      v_route:='/chat/[threadId]';
    else return null;
  end case;
  if v_owner is null or v_status is distinct from v_expected or v_action_at is distinct from p_report.resolved_at
    or (p_report.target_type<>'profile_media' and v_action_by is distinct from p_report.resolved_by::text)
    or public.admin_reports_safe_uuid(v_owner) is null
    or not exists(select 1 from auth.users where id=v_owner::uuid) then return null; end if;
  return jsonb_build_object('owner',v_owner,'route',v_route,'threadId',v_thread,'targetType',p_report.target_type,
    'targetId',v_target,'resolution',p_report.resolution_type);
end $$;
revoke all on function private.notification_moderation_target(public.safety_reports) from public,anon,authenticated,service_role;

create function private.enqueue_moderation_notification_activity()
returns trigger language plpgsql security definer set search_path='' as $$
declare v_target jsonb;
begin
  if new.status<>'actioned' or (old.status=new.status and old.resolution_type is not distinct from new.resolution_type
    and old.resolved_at is not distinct from new.resolved_at) then return new; end if;
  v_target:=private.notification_moderation_target(new);
  if v_target is null then return new; end if;
  perform private.enqueue_notification_activity('moderation-decision:'||new.id::text||':'||new.resolved_at::text||':'||new.resolution_type,
    'moderation_notice',new.id::text,null,(v_target->>'owner')::uuid,
    jsonb_build_object('resolution',new.resolution_type,'resolvedAt',new.resolved_at));
  return new;
end $$;
revoke all on function private.enqueue_moderation_notification_activity() from public,anon,authenticated,service_role;
create trigger enqueue_moderation_notification_activity after update of status,resolution_type,resolved_at on public.safety_reports
  for each row execute function private.enqueue_moderation_notification_activity();

create or replace function private.resolve_account_notification_activity(p_event public.notification_activity_events)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_report public.safety_reports; v_target jsonb;
begin
  if p_event.event_kind<>'moderation_notice' or p_event.actor_user_id is not null or p_event.source_id !~ '^[0-9]{1,18}$'
    then return '{"eligible":false}'; end if;
  select * into v_report from public.safety_reports where id=p_event.source_id::bigint;
  if not found or v_report.resolution_type is distinct from p_event.context->>'resolution'
    or to_jsonb(v_report.resolved_at) is distinct from p_event.context->'resolvedAt' then return '{"eligible":false}'; end if;
  v_target:=private.notification_moderation_target(v_report);
  if v_target is null or v_target->>'owner' is distinct from p_event.recipient_user_id::text then return '{"eligible":false}'; end if;
  return jsonb_build_object('eligible',true,'category','moderation_notice','notification_type','moderation_notice',
    'title','Content moderation update','body',case v_report.resolution_type
      when 'target_hidden' then 'Your content was hidden after review.'
      when 'target_removed' then 'Your content was removed after review.'
      else 'Your content was restored after review.' end,
    'target_route',v_target->>'route','target_entity_id',case when v_target->>'route'='/profile/[userId]' then p_event.recipient_user_id::text
      when v_target->>'route'='/chat/[threadId]' then v_target->>'threadId' else null end,
    'target_context',jsonb_build_object('resolution',v_report.resolution_type),
    'preference_key','account_activity_enabled');
end $$;
revoke all on function private.resolve_account_notification_activity(public.notification_activity_events) from public,anon,authenticated,service_role;
